import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a sharp box-like component, and a low frequency gaussian component to shape the landscape.

    Formula:
    f(x) = sum(cos(5*x)) + 0.1* box_component(x) + 0.05 * gaussian_component(x)

    where:
    box_component(x) = 1 if all(abs(x) < 0.5) else 0
    gaussian_component(x) = exp(-0.5 * sum(x**2)/9)
    """

    def box_component(x):
        if np.all(np.abs(x) < 0.5):
            return 1.0
        else:
            return 0.0

    def gaussian_component(x):
        return np.exp(-0.5 * np.sum(x**2)/9)

    return np.sum(np.cos(5*x)) + 0.1 * box_component(x) + 0.05 * gaussian_component(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a skewed polynomial component, a Gaussian component, and an interaction term.

    Formula:
    f(x) = sum(cos(5*x)) + 0.05* skewed_poly(x) + 0.1 * gaussian_component(x) + 0.02 * interaction_term(x)

    where:
    skewed_poly(x) = sum(x**4 + 0.1*x**3)
    gaussian_component(x) = exp(-0.5 * sum(x**2)/0.5)
    interaction_term(x) = sum(x * cos(5*x))
    """

    def skewed_poly(x):
        return np.sum(x**4 + 0.1*x**3)

    def gaussian_component(x):
        return np.exp(-0.5 * np.sum(x**2)/0.5) #Decreased denominator to make gaussian narrower

    def interaction_term(x):
       return np.sum(x * np.cos(5*x))

    return np.sum(np.cos(5*x)) + 0.05 * skewed_poly(x) + 0.1 * gaussian_component(x) + 0.02 * interaction_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a 'soft' box-like component, a quadratic component and a gaussian component to shape the landscape.

    Formula:
    f(x) = 2 * (sum(cos(5*x)) + 0.1* box_component(x) + sum(x**2)/25 + 0.01 * gaussian_component(x))

    where:
    box_component(x) = exp(-sum(x**2) / 0.5)
    gaussian_component(x) = exp(-0.5 * sum(x**2)/9)
    """

    def box_component(x):
        return np.exp(-np.sum(x**2) / 0.5)

    def gaussian_component(x):
        return np.exp(-0.5 * np.sum(x**2)/9)


    return 2*(np.sum(np.cos(5*x)) + 0.1 * box_component(x) + np.sum(x**2)/25 + 0.01 * gaussian_component(x))

