import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a polynomial term, a 'soft' step function and an exponential term to shape the landscape.

    Formula:
    f(x) = sum(cos(5*x)) + 0.2*polynomial_term(x) + step_function(x) + 0.05 * np.exp(-0.1 * sum(x**2))

    where:
    polynomial_term(x) = sum((x**3)/5) # Cubic term for asymmetry
    step_function(x) = sum(np.where(x > 1, 1, 0)) # Mimic discrete changes
    """

    def polynomial_term(x):
        return np.sum((x**3)/5)

    def step_function(x):
          return np.sum(np.where(x>1, 1,0))

    return np.sum(np.cos(5*x)) + 0.2*polynomial_term(x) + step_function(x) + 0.05 * np.exp(-0.1 * np.sum(x**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a 'soft' box-like component, a quadratic component, a simple linear function,
    and a gaussian component to shape the landscape.  Pairwise variable interactions are also introduced.

    Formula:
    f(x) = 3*(0.8 * (sum(cos(5*x)) + 0.1* box_component(x) + sum(x**2)/25 + 0.01 * gaussian_component(x)) \
     + 0.05 * np.product(x[0:2]) + 0.01 * np.sum(x) + 0.02 * sum_of_pair_product(x))

    where:
    box_component(x) = exp(-sum(x**2) / 0.5)
    gaussian_component(x) = exp(-0.5 * sum(x**2)/9)
    sum_of_pair_product(x) = sum_{i<j} x_i*x_j
    """

    def box_component(x):
        return np.exp(-np.sum(x**2) / 0.5)

    def gaussian_component(x):
        return np.exp(-0.5 * np.sum(x**2)/9)

    def sum_of_pair_product(x):
        s = 0
        for i in range(len(x)):
            for j in range(i+1, len(x)):
                s += x[i]*x[j]
        return s

    return 3*(0.8*(np.sum(np.cos(5*x)) + 0.1 * box_component(x) + np.sum(x**2)/25 + 0.01 * gaussian_component(x)) \
     + 0.05 * np.product(x[0:2]) + 0.01 * np.sum(x) + 0.02* sum_of_pair_product(x))

