import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal component with varying frequencies, a radial bias function, and a quadratic term.

    Formula:
    f(x) = sum(cos(3*x) + 0.5*cos(7*x)) + 0.2*rbf(x) + 0.05*sum(x**2)

    where:
    rbf(x) = exp(- sum(x**2) / 10)
    """

    def rbf(x):
        return np.exp(-np.sum(x**2) / 10)

    return np.sum(np.cos(3*x) + 0.5*np.cos(7*x)) + 0.2*rbf(x) + 0.05*np.sum(x**2)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a skewed cosinoidal ripple, a box-like component, a quadratic component and a scaled Rosenbrock component to shape the landscape. It has an attempt to increase interaction.

    Formula:
    f(x) = np.sum(np.cos(5*(x + 0.1))) + 0.1 * box_component(x) + 0.2 * rosenbrock(x) + 0.05*np.sum(x**2)/25  + 0.03 * np.sum(x)

    where:
    box_component(x) = np.exp(-np.sum(x**2) / 0.75)
    rosenbrock(x) = np.sum(100.0 * (x[1:] - x[:-1]**2.0)**2.0 + (1 - x[:-1])**2.0)
    """

    def box_component(x):
        return np.exp(-np.sum(x**2) / 0.75)

    def rosenbrock(x):
        return np.sum(100.0 * (x[1:] - x[:-1]**2.0)**2.0 + (1 - x[:-1])**2.0)

    return np.sum(np.cos(5*(x + 0.1))) + 0.1 * box_component(x) + 0.2 * rosenbrock(x) + 0.05*np.sum(x**2)/25 + 0.03 * np.sum(x)

import numpy as np


def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a 'soft' box-like component, a quadratic component, a gaussian component, and a linear term to shape the landscape.
    The contributions of each term are refined to better match the target ELA features.

    Formula:
    f(x) = 1.5 * np.sum(np.cos(4*x)) + 0.02 * box_component(x) + 0.08*np.sum(x) + np.sum(x**2)/8 + 0.002 * gaussian_component(x)

    where:
    box_component(x) = np.exp(-np.sum(x**2) / 0.75)
    gaussian_component(x) = np.exp(-0.5 * np.sum(x**2)/20) + 2* np.sum(np.sin(x))
    """

    def box_component(x):
        return np.exp(-np.sum(x**2) / 0.75)

    def gaussian_component(x):
        return np.exp(-0.5 * np.sum(x**2)/20)

    return 1.5 * np.sum(np.cos(4*x)) + 0.02 * box_component(x) + 0.08*np.sum(x) + np.sum(x**2)/8 + 0.002 * gaussian_component(x)

