def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, an absolute box-like component, a quadratic component, a cubic component, and a gaussian component to shape the landscape.

    Formula:
    f(x) = 5*(0.6 * sum(cos(5*x)) + 0.2 * abs_box_component(x) + 0.15 * sum(x**2)/25 - 0.05*sum(np.abs(x)**3)/125 + 0.02 * gaussian_component(x))

    where:
    abs_box_component(x) = np.exp(-np.sum(np.abs(x)) / 0.5)
    gaussian_component(x) = np.exp(-0.5 * sum(x**2)/9)
    """

    def abs_box_component(x):
        return np.exp(-np.sum(np.abs(x)) / 0.5)

    def gaussian_component(x):
        return np.exp(-0.5 * np.sum(x**2)/9)


    return 5*(0.6 * np.sum(np.cos(5*x)) + 0.2 * abs_box_component(x) + 0.15 * np.sum(x**2)/25 - 0.05*np.sum(np.abs(x)**3)/125 + 0.02 * gaussian_component(x))

