import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    This function combines a periodic component, a radial component, a linear trend, and quadratic terms (both independent and with interaction) to sculpt the landscape.

    Formula:
    f(x) = np.sum(np.sin(2*x) + np.cos(x)) + radial_component(x) + 0.1*np.sum(x) + 0.05 * np.sum(x**2)/25 +  interaction_term(x)

    where:
    radial_component(x) = np.exp(-np.linalg.norm(x)**2 / 10)
    interaction_term(x) = np.sum(x * np.roll(x, 1)) / 100
    """

    def radial_component(x):
        return np.exp(-np.linalg.norm(x)**2 / 10)

    def interaction_term(x):
        return np.sum(x * np.roll(x, 1)) / 100

    return np.sum(np.sin(2*x) + np.cos(x)) + radial_component(x) + 0.1*np.sum(x) + 0.05 * np.sum(x**2)/25 +  interaction_term(x)

