import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a cosinoidal ripple, a 'soft' box-like component, a quadratic component, a gaussian component, a cubic component and an interaction term to shape the landscape.

    Formula:
    f(x) = 2 * (1.0*sum(cos(5*x)) + 0.05 * box_component(x) + 1.0*sum(x**2)/25 + 0.005 * gaussian_component(x) + 0.001 * sum(x**3)/25 + 0.005 * interaction_term(x))

    where:
    box_component(x) = exp(-sum(x**2) / 0.5)
    gaussian_component(x) = exp(-0.5 * sum(x**2)/9)
    interaction_term(x) = np.prod(x) #product of all variables
    """

    def box_component(x):
        return np.exp(-np.sum(x**2) / 0.5)

    def gaussian_component(x):
