import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function mimicking specific ELA features.

    The function combines a periodic component based on sine waves, a polynomial distortion function, and a component to add local minima.

    Formula:
    f(x) = np.sum(np.sin(x) + 0.5 * np.sin(2*x))  + polynomial_distortion(x) + 0.1 * local_minima(x)

    where:
     polynomial_distortion(x) = 0.05 * np.sum(x**3) + 0.01 * np.sum(x**4)
     local_minima(x) = np.sum(np.cos(3*x)) + np.sum(x**2/2) / 10

    """

    def polynomial_distortion(x):
      return 0.05 * np.sum(x**3) + 0.01 * np.sum(x**4)

    def local_minima(x):
      return np.sum(np.cos(3*x)) + np.sum(x**2/2) / 10

    return np.sum(np.sin(x) + 0.5 * np.sin(2*x)) + polynomial_distortion(x) + 0.1 * local_minima(x)

